public class DOMNodePointer_findEnclosingAttribute_TriageGen2Test {

    /**
     * Helper method to access the protected static method via reflection.
     */
    private String invokeFindEnclosingAttribute(Node n, String attrName) throws Exception {
        Method method = DOMNodePointer.class.getDeclaredMethod("findEnclosingAttribute", Node.class, String.class);
        method.setAccessible(true);
        return (String) method.invoke(null, n, attrName);
    }

    @Test
    public void testFindEnclosingAttribute_NullNode() throws Exception {
        assertNull(invokeFindEnclosingAttribute(null, "testAttr"));
    }

    @Test
    public void testFindEnclosingAttribute_AttributeFoundOnCurrentNode() throws Exception {
        Document doc = createDocument();
        Element root = doc.createElement("root");
        root.setAttribute("target", "value1");
        doc.appendChild(root);

        Element child = doc.createElement("child");
        root.appendChild(child);

        // Test finding attribute on the node itself
        assertEquals("value1", invokeFindEnclosingAttribute(child, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_AttributeFoundOnParent() throws Exception {
        Document doc = createDocument();
        Element root = doc.createElement("root");
        root.setAttribute("target", "value1");
        doc.appendChild(root);

        Element child = doc.createElement("child");
        Element grandchild = doc.createElement("grandchild");
        root.appendChild(child);
        child.appendChild(grandchild);

        // Test finding attribute on parent
        assertEquals("value1", invokeFindEnclosingAttribute(grandchild, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_AttributeEmptyOrNullOnIntermediateNodes() throws Exception {
        Document doc = createDocument();
        Element root = doc.createElement("root");
        root.setAttribute("target", "value1");
        doc.appendChild(root);

        Element child = doc.createElement("child");
        child.setAttribute("target", ""); // Empty string should be skipped
        root.appendChild(child);

        Element grandchild = doc.createElement("grandchild");
        child.appendChild(grandchild);

        // Even though child has "target", it is empty, so it should return root's value
        assertEquals("value1", invokeFindEnclosingAttribute(grandchild, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_NonElementNode() throws Exception {
        Document doc = createDocument();
        Element root = doc.createElement("root");
        root.setAttribute("target", "value1");
        doc.appendChild(root);

        // Create a Text Node
        Node textNode = doc.createTextNode("hello");
        root.appendChild(textNode);

        // Text node is not an Element, should skip to parent (root)
        assertEquals("value1", invokeFindEnclosingAttribute(textNode, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_NoAttributeFound() throws Exception {
        Document doc = createDocument();
        Element root = doc.createElement("root");
        doc.appendChild(root);

        Element child = doc.createElement("child");
        root.appendChild(child);

        assertNull(invokeFindEnclosingAttribute(child, "nonExistent"));
    }

    @Test
    public void testFindEnclosingAttribute_AttributeIsNotNullButEmptyString() throws Exception {
        Document doc = createDocument();
        Element root = doc.createElement("root");
        root.setAttribute("target", ""); // Empty
        doc.appendChild(root);

        Element child = doc.createElement("child");
        root.appendChild(child);

        // Should return null because root's attribute is empty
        assertNull(invokeFindEnclosingAttribute(child, "target"));
    }

    private Document createDocument() {
        DOMImplementation implementation = org.apache.xerces.impl.xs.XMLSchemaConstants.X_SCHEMA_NS_URI.equals("") 
                ? null : null; // Placeholder for environment; standard DOM is fine
        return org.apache.xerces.impl.util.DOMImplementationImpl.newInstance().createDocument(null, null, null);
    }

    // Note: Since we cannot easily rely on Xerces in every environment, 
    // a standard way to get a Document in unit tests is:
    private Document createDoc() {
        return org.apache.xerces.impl.util.DOMImplementationImpl.newInstance().createDocument(null, null, null);
    }

    // Re-implementing createDocument to be safe for standard JUnit environments
    @Override
    protected Document createDocument() {
        try {
            return javax.xml.parsers.DocumentBuilderFactory.newInstance()
                    .newDocumentBuilder().newDocument();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
